CREATE TABLE launch_rounds(id TEXT PRIMARY KEY,title TEXT NOT NULL,stage TEXT NOT NULL DEFAULT 'lobby' CHECK(stage IN('lobby','contract','banking','investigation','review','completed')),team_size INTEGER NOT NULL CHECK(team_size BETWEEN 1 AND 100),creator TEXT NOT NULL REFERENCES users(id),launch_at INTEGER,incident_at INTEGER,version INTEGER NOT NULL DEFAULT 1,created_at INTEGER NOT NULL);
CREATE UNIQUE INDEX launch_one_live_round ON launch_rounds((1)) WHERE stage!='completed';
CREATE TABLE launch_players(round_id TEXT NOT NULL REFERENCES launch_rounds(id),user_id TEXT NOT NULL REFERENCES users(id),team TEXT NOT NULL CHECK(team IN('red','blue')),ready INTEGER NOT NULL DEFAULT 0 CHECK(ready IN(0,1)),terms_at INTEGER,terms_version TEXT,joined_at INTEGER NOT NULL,PRIMARY KEY(round_id,user_id));
CREATE TABLE launch_wallets(id TEXT PRIMARY KEY,round_id TEXT NOT NULL REFERENCES launch_rounds(id),user_id TEXT REFERENCES users(id),name TEXT NOT NULL,iban TEXT NOT NULL,balance INTEGER NOT NULL DEFAULT 0 CHECK(balance>=0),UNIQUE(round_id,user_id),UNIQUE(round_id,iban));
CREATE TABLE launch_transactions(id TEXT PRIMARY KEY,round_id TEXT NOT NULL REFERENCES launch_rounds(id),sender TEXT REFERENCES launch_wallets(id),recipient TEXT NOT NULL REFERENCES launch_wallets(id),amount INTEGER NOT NULL CHECK(amount>0),kind TEXT NOT NULL CHECK(kind IN('allocation','transfer','incident')),note TEXT NOT NULL,request_key TEXT NOT NULL,created_at INTEGER NOT NULL,batch_ref TEXT,UNIQUE(round_id,request_key));
CREATE TABLE launch_incidents(round_id TEXT PRIMARY KEY REFERENCES launch_rounds(id),actor TEXT NOT NULL REFERENCES users(id),created_at INTEGER NOT NULL,ref TEXT NOT NULL DEFAULT 'BATCH-041');
CREATE TABLE launch_evidence(round_id TEXT NOT NULL REFERENCES launch_rounds(id),ref TEXT NOT NULL,category TEXT NOT NULL,title TEXT NOT NULL,occurred_at INTEGER NOT NULL,body TEXT NOT NULL,PRIMARY KEY(round_id,ref));
CREATE TABLE launch_pins(round_id TEXT NOT NULL,team TEXT NOT NULL CHECK(team IN('red','blue')),ref TEXT NOT NULL,actor TEXT NOT NULL REFERENCES users(id),created_at INTEGER NOT NULL,PRIMARY KEY(round_id,team,ref),FOREIGN KEY(round_id,ref) REFERENCES launch_evidence(round_id,ref));
CREATE TABLE launch_notes(id TEXT PRIMARY KEY,round_id TEXT NOT NULL REFERENCES launch_rounds(id),team TEXT NOT NULL CHECK(team IN('red','blue')),actor TEXT NOT NULL REFERENCES users(id),body TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE launch_reports(id TEXT PRIMARY KEY,round_id TEXT NOT NULL REFERENCES launch_rounds(id),team TEXT NOT NULL CHECK(team IN('red','blue')),actor TEXT NOT NULL REFERENCES users(id),payload TEXT NOT NULL,submitted_at INTEGER NOT NULL,request_key TEXT NOT NULL,UNIQUE(round_id,request_key));
CREATE TABLE launch_verdicts(round_id TEXT PRIMARY KEY REFERENCES launch_rounds(id),winner TEXT NOT NULL CHECK(winner IN('red','blue','draw')),grades TEXT NOT NULL,reason TEXT NOT NULL,actor TEXT NOT NULL REFERENCES users(id),created_at INTEGER NOT NULL);
CREATE TABLE launch_events(id INTEGER PRIMARY KEY AUTOINCREMENT,round_id TEXT NOT NULL REFERENCES launch_rounds(id),actor TEXT REFERENCES users(id),event TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE INDEX launch_reports_order ON launch_reports(round_id,submitted_at);
CREATE INDEX launch_transactions_order ON launch_transactions(round_id,created_at);
CREATE INDEX launch_notes_order ON launch_notes(round_id,team,created_at);
CREATE TRIGGER launch_student_join BEFORE INSERT ON launch_players BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM users u JOIN launch_rounds r ON r.id=NEW.round_id WHERE u.id=NEW.user_id AND u.role='customer' AND u.status='active' AND r.stage='lobby') THEN RAISE(ABORT,'Launch player not eligible') END; SELECT CASE WHEN (SELECT COUNT(*) FROM launch_players WHERE round_id=NEW.round_id AND team=NEW.team AND user_id!=NEW.user_id)>=(SELECT team_size FROM launch_rounds WHERE id=NEW.round_id) THEN RAISE(ABORT,'Launch team full') END; END;
CREATE TRIGGER launch_student_move BEFORE UPDATE OF team ON launch_players WHEN OLD.team!=NEW.team BEGIN SELECT CASE WHEN (SELECT stage FROM launch_rounds WHERE id=NEW.round_id)!='lobby' THEN RAISE(ABORT,'Launch roster locked') END; SELECT CASE WHEN (SELECT COUNT(*) FROM launch_players WHERE round_id=NEW.round_id AND team=NEW.team AND user_id!=NEW.user_id)>=(SELECT team_size FROM launch_rounds WHERE id=NEW.round_id) THEN RAISE(ABORT,'Launch team full') END; END;
CREATE TRIGGER launch_tx_guard BEFORE INSERT ON launch_transactions BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM launch_wallets WHERE id=NEW.recipient AND round_id=NEW.round_id) THEN RAISE(ABORT,'Launch recipient invalid') END;
 SELECT CASE WHEN NEW.kind!='allocation' AND NOT EXISTS(SELECT 1 FROM launch_wallets WHERE id=NEW.sender AND round_id=NEW.round_id AND balance>=NEW.amount) THEN RAISE(ABORT,'Launch insufficient balance') END;
 SELECT CASE WHEN NEW.kind='transfer' AND NOT EXISTS(SELECT 1 FROM launch_rounds r JOIN launch_wallets w ON w.round_id=r.id JOIN launch_players p ON p.round_id=r.id AND p.user_id=w.user_id JOIN users u ON u.id=p.user_id WHERE r.id=NEW.round_id AND r.stage IN('banking','investigation') AND w.id=NEW.sender AND p.terms_at IS NOT NULL AND u.status='active' AND u.role='customer') THEN RAISE(ABORT,'Launch transfer not allowed') END;
 SELECT CASE WHEN NEW.kind='incident' AND NOT EXISTS(SELECT 1 FROM launch_incidents WHERE round_id=NEW.round_id) THEN RAISE(ABORT,'Launch incident missing') END;
END;
CREATE TRIGGER launch_tx_apply AFTER INSERT ON launch_transactions BEGIN UPDATE launch_wallets SET balance=balance-NEW.amount WHERE id=NEW.sender; UPDATE launch_wallets SET balance=balance+NEW.amount WHERE id=NEW.recipient; END;
CREATE TRIGGER launch_wallet_allocate AFTER INSERT ON launch_wallets WHEN NEW.user_id IS NOT NULL BEGIN INSERT INTO launch_transactions(id,round_id,recipient,amount,kind,note,request_key,created_at) VALUES(lower(hex(randomblob(16))),NEW.round_id,NEW.id,5000000,'allocation','Level 1 starting allocation · DEMO ALL','allocation:'||NEW.id,CAST(strftime('%s','now') AS INTEGER)*1000); END;
CREATE TRIGGER launch_incident_guard BEFORE INSERT ON launch_incidents BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM users WHERE id=NEW.actor AND role='owner' AND status='active') THEN RAISE(ABORT,'Launch owner required') END;
 SELECT CASE WHEN (SELECT stage FROM launch_rounds WHERE id=NEW.round_id)!='banking' THEN RAISE(ABORT,'Launch wrong stage') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM launch_players p JOIN users u ON u.id=p.user_id WHERE p.round_id=NEW.round_id AND p.terms_at IS NOT NULL AND u.role='customer' AND u.status='active') THEN RAISE(ABORT,'Launch no players') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM launch_wallets w JOIN launch_players p ON p.round_id=w.round_id AND p.user_id=w.user_id JOIN users u ON u.id=p.user_id WHERE w.round_id=NEW.round_id AND u.role='customer' AND u.status='active' AND (w.balance<1000000 OR p.terms_at IS NULL)) THEN RAISE(ABORT,'Launch incident preflight failed') END;
END;
CREATE TRIGGER launch_incident_apply AFTER INSERT ON launch_incidents BEGIN
 INSERT INTO launch_transactions(id,round_id,sender,recipient,amount,kind,note,request_key,created_at,batch_ref) SELECT lower(hex(randomblob(16))),NEW.round_id,w.id,(SELECT id FROM launch_wallets WHERE round_id=NEW.round_id AND user_id IS NULL),1000000,'incident','Simulated unauthorized transfer · investigate related records','incident:'||w.id,NEW.created_at,'BATCH-041' FROM launch_wallets w JOIN launch_players p ON p.round_id=w.round_id AND p.user_id=w.user_id JOIN users u ON u.id=p.user_id WHERE w.round_id=NEW.round_id AND u.role='customer' AND u.status='active' AND p.terms_at IS NOT NULL;
 UPDATE launch_rounds SET stage='investigation',incident_at=NEW.created_at,version=version+1 WHERE id=NEW.round_id;
END;

CREATE TRIGGER launch_pin_guard BEFORE INSERT ON launch_pins BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM launch_rounds r JOIN launch_players p ON p.round_id=r.id JOIN users u ON u.id=p.user_id WHERE r.id=NEW.round_id AND r.stage='investigation' AND p.user_id=NEW.actor AND p.team=NEW.team AND u.role='customer' AND u.status='active') THEN RAISE(ABORT,'Launch evidence is frozen or unauthorized') END; END;
CREATE TRIGGER launch_note_guard BEFORE INSERT ON launch_notes BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM launch_rounds r JOIN launch_players p ON p.round_id=r.id JOIN users u ON u.id=p.user_id WHERE r.id=NEW.round_id AND r.stage='investigation' AND p.user_id=NEW.actor AND p.team=NEW.team AND u.role='customer' AND u.status='active') THEN RAISE(ABORT,'Launch notes are frozen or unauthorized') END; END;
CREATE TRIGGER launch_report_guard BEFORE INSERT ON launch_reports BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM launch_rounds r JOIN launch_players p ON p.round_id=r.id JOIN users u ON u.id=p.user_id WHERE r.id=NEW.round_id AND r.stage='investigation' AND p.user_id=NEW.actor AND p.team=NEW.team AND u.role='customer' AND u.status='active') THEN RAISE(ABORT,'Launch report is frozen or unauthorized') END; END;
